import itertools

def gf23_add(a, b):
    return a ^ b

def gf23_mul(a, b):
    if a == 0 or b == 0:
        return 0
    # Log table for p(x) = x^3 + x + 1
    # alpha^0=1, alpha^1=2, alpha^2=4, alpha^3=3, alpha^4=6, alpha^5=7, alpha^6=5
    log = {1: 0, 2: 1, 4: 2, 3: 3, 6: 4, 7: 5, 5: 6}
    exp = {0: 1, 1: 2, 2: 4, 3: 3, 4: 6, 5: 7, 6: 5}
    res_log = (log[a] + log[b]) % 7
    return exp[res_log]

elements = [0, 1, 2, 3, 4, 5, 6, 7]

# Try all pairs of multipliers (a, b) where a, b != 0 and a != b
for a in range(1, 8):
    for b in range(1, 8):
        if a == b:
            continue

        X = [[0 for _ in range(8)] for _ in range(8)]
        Y = [[0 for _ in range(8)] for _ in range(8)]

        for i in range(8):
            for j in range(8):
                X[i][j] = gf23_add(gf23_mul(a, elements[i]), elements[j])
                Y[i][j] = gf23_add(gf23_mul(b, elements[i]), elements[j])

        # Check orthogonality
        pairs = set()
        for i in range(8):
            for j in range(8):
                pairs.add((X[i][j], Y[i][j]))

        if len(pairs) == 64:
            print(f"Found: a={a}, b={b}")
            # Flatten
            result = []
            for row in X:
                result.extend(row)
            for row in Y:
                result.extend(row)
            print(result)
            break
    else:
        continue
    break

