def is_latin(square):
    for row in square:
        if sorted(row) != list(range(8)):
            return False
    for col in range(8):
        if sorted([square[row][col] for row in range(8)]) != list(range(8)):
            return False
    return True

def are_orthogonal(X, Y):
    pairs = set()
    for i in range(8):
        for j in range(8):
            pair = (X[i][j], Y[i][j])
            if pair in pairs:
                return False
            pairs.add(pair)
    return len(pairs) == 64

